<?php
namespace qqworld_collector\module\collect_filter; use qqworld_collector\lib; class qqworld_collector_parse_baike_com_post_content extends lib { var $post_content = array(); public function __construct() { add_filter( 'qqworld-collector-parse-baike-com-post-content', array($this, 'filter'), 10, 6 ); } public function filter($item, $source_link, $html, $type, $item_args, $download_args) { $json = json_decode($item, true); if ($json) { $item = ''; foreach ($json as $it) { switch ($it['type']) { case 'heading': $item .= "<h{$it['attrs']['level']}>"; foreach ($it['content'] as $con) { switch ($con['type']) { case 'text': $item .= $con['text']; break; } } $item .= "</h{$it['attrs']['level']}>"; break; case 'paragraph': foreach ($it['content'] as $con) { $item .= '<p>'; switch ($con['type']) { case 'text': $item .= $con['text']; break; case 'image': $item .= '<img src="'.$con['attrs']['uri'].'" alt="'.$con['attrs']['alt'].'" title="'.$con['attrs']['title'].'" width="'.$con['attrs']['width'].'" height="'.$con['attrs']['height'].'" />'; break; } $item .= '</p>'; } break; case 'table': $item .= '<table class="bk-table">'; foreach ($it['content'] as $row) { $item .= '<tr>'; switch ($row['type']) { case 'table_row': foreach ($row['content'] as $con) { $attrs = ''; foreach ($con['attrs'] as $key => $value) { if ($value) $attrs .= ' ' . $key . '="' . $value . '"'; } $item .= '<td'.$attrs.'>'; switch ($con['type']) { case 'table_header': case 'table_cell': foreach ($con['content'] as $co) { switch ($co['type']) { case 'paragraph': foreach ($co['content'] as $c) { switch ($c['type']) { case 'text': $item .= '<p>' . $c['text'] . '</p>'; break; } } break; } } break; } $item .= '</td>'; } break; } $item .= '</tr>'; } $item .= '<table>'; break; } } } return $item; } } new qqworld_collector_parse_baike_com_post_content; ?>